import Foundation
import CryptoKit

/// Local policy only. Neither labels nor permissions are generated by the model.
enum AssistantPrivacy {
    static func containsSecret(_ text: String, key: String = "") -> Bool {
        if !key.isEmpty, text.contains(key) { return true }
        let patterns = [#"(?i)\b(?:sk|xai)-[a-z0-9_-]{12,}"#,
                        #"-----BEGIN [A-Z ]*PRIVATE KEY-----"#,
                        #"(?i)(?:bearer\s+|(?:api[_ -]?key|password|token|密码|密钥)\s*[:=：]\s*)[^\s\"，,]{8,}"#]
        return patterns.contains { text.range(of: $0, options: .regularExpression) != nil }
    }

    static func check(_ body: Data, key: String) throws {
        func inspect(_ value: Any) -> Bool {
            if let value = value as? String { return containsSecret(value, key: key) }
            if let values = value as? [Any] { return values.contains(where: inspect) }
            if let object = value as? [String: Any] {
                // Provider-owned opaque continuation is not a user credential.
                return object.contains { $0.key != "encrypted_content" && inspect($0.value) }
            }
            return false
        }
        if inspect(try JSONSerialization.jsonObject(with: body)) { throw AssistantError.sensitive }
    }

    static func category(_ tool: String) -> String {
        switch tool {
        case "list_courses": "课程名称、类型和自动排课状态"
        case "inspect_course": "课程和课节名称、时长、进度与截止日期"
        case "inspect_schedule": "课程编号、时间、具体安排与排课依据"
        case "inspect_progress": "计划时长、实际学习量与完成记录统计"
        case "inspect_settings": "可学习时段、排课偏好与提醒设置"
        case "inspect_runtime": "保存、同步和监督等运行状态摘要"
        case "inspect_compression": "已保存的压缩方案摘要"
        case "preview_schedule_change": "拟调整的课程和本机计算的日程预览"
        default: "软件功能说明"
        }
    }

    static func scope(_ call: AssistantToolCall) -> String {
        guard let object = try? JSONSerialization.jsonObject(with: Data(call.arguments.utf8)),
              let data = try? JSONSerialization.data(withJSONObject: object, options: [.sortedKeys]) else { return call.name }
        return call.name + ":" + String(decoding: data, as: UTF8.self)
    }

    static func scopeDescription(_ scope: String) -> String {
        guard let split = scope.firstIndex(of: ":"),
              let args = try? JSONSerialization.jsonObject(with: Data(scope[scope.index(after: split)...].utf8)) as? [String: Any] else { return "本次查询范围" }
        let labels = ["course": "课程", "date": "日期", "start_date": "开始日期", "end_date": "结束日期", "offset": "起始项", "action": "调整类型", "value": "调整值"]
        let parts = args.keys.sorted().compactMap { key -> String? in
            guard let label = labels[key], let value = args[key] else { return nil }
            let text = String(describing: value)
            return label + "：" + (text.isEmpty ? "当前概览" : text)
        }
        return parts.isEmpty ? "当前状态摘要" : parts.joined(separator: " · ")
    }

    static func grantKey(_ result: AssistantToolResult) -> String {
        // Capture time is not a data change; all payload facts, scope and labels are.
        let payload = result.content.drop(while: { $0 != " " }).dropFirst()
        var object = (try? JSONSerialization.jsonObject(with: Data(payload.utf8))) as? [String: Any] ?? [:]
        object.removeValue(forKey: "captured_at")
        let data = (try? JSONSerialization.data(withJSONObject: object, options: [.sortedKeys])) ?? Data(result.content.utf8)
        return result.scope + ":" + SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}
